import{_ as i,c as a,o,a0 as e}from"./chunks/framework.DKRgXLPU.js";const t=JSON.parse('{"title":"Introduzione al gioco mentale - Diapositive per il facilitatore","description":"","frontmatter":{},"headers":[],"relativePath":"public/downloads/it/facilitator-slides.md","filePath":"public/downloads/it/facilitator-slides.md"}');const r=i({name:"public/downloads/it/facilitator-slides.md"},[["render",function(i,t,r,n,s,l){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="introduzione-al-gioco-mentale-diapositive-per-il-facilitatore" tabindex="-1">Introduzione al gioco mentale - Diapositive per il facilitatore <a class="header-anchor" href="#introduzione-al-gioco-mentale-diapositive-per-il-facilitatore" aria-label="Permalink to &quot;Introduzione al gioco mentale - Diapositive per il facilitatore&quot;">​</a></h1><p><strong>Accademia di bocce</strong><em>Guida alla sessione per facilitatori</em></p><hr><h2 id="diapositiva-1-benvenuti" tabindex="-1">Diapositiva 1: Benvenuti <a class="header-anchor" href="#diapositiva-1-benvenuti" aria-label="Permalink to &quot;Diapositiva 1: Benvenuti&quot;">​</a></h2><h1 id="🎯-introduzione-al-gioco-mentale" tabindex="-1">🎯 Introduzione al gioco mentale <a class="header-anchor" href="#🎯-introduzione-al-gioco-mentale" aria-label="Permalink to &quot;🎯 Introduzione al gioco mentale&quot;">​</a></h1><p><strong>Per giocatori di bocce d&#39;élite</strong></p><h3 id="oggi-scoprirai" tabindex="-1">Oggi scoprirai: <a class="header-anchor" href="#oggi-scoprirai" aria-label="Permalink to &quot;Oggi scoprirai:&quot;">​</a></h3><ul><li>🧠 Come creare le giuste condizioni per &quot;la zona&quot;</li><li>💪 Come mettere a tacere il tuo critico interiore</li><li>🎪 Strumenti pratici che funzionano sotto pressione</li></ul><p><strong>Preparatevi per una sessione interattiva!</strong></p><hr><h2 id="diapositiva-2-sondaggio-rapido-alzate-la-mano-🙋" tabindex="-1">Diapositiva 2: Sondaggio rapido - Alzate la mano! 🙋 <a class="header-anchor" href="#diapositiva-2-sondaggio-rapido-alzate-la-mano-🙋" aria-label="Permalink to &quot;Diapositiva 2: Sondaggio rapido - Alzate la mano! 🙋&quot;">​</a></h2><h3 id="chi-ha-vissuto-questa-esperienza" tabindex="-1">Chi ha vissuto questa esperienza? <a class="header-anchor" href="#chi-ha-vissuto-questa-esperienza" aria-label="Permalink to &quot;Chi ha vissuto questa esperienza?&quot;">​</a></h3><p><strong>Alzate la mano se vi è mai capitato di:</strong></p><ol><li><p>Hai fatto un tiro perfetto in allenamento... e poi l&#39;hai sbagliato in gara? 🎯❌</p></li><li><p>Hai sentito la tua mente correre quando avevi bisogno di mantenere la calma? 🧠💨</p></li><li><p>Ti sei criticato dopo un errore? 😤</p></li><li><p>Hai mai avuto un gioco in cui tutto &quot;faceva clic&quot;? ✨</p></li></ol><p><strong>Non sei solo! Risolviamo questo problema insieme.</strong></p><hr><h2 id="diapositiva-3-il-paradosso-del-giocatore-d-39-elite" tabindex="-1">Diapositiva 3: Il paradosso del giocatore d&#39;élite <a class="header-anchor" href="#diapositiva-3-il-paradosso-del-giocatore-d-39-elite" aria-label="Permalink to &quot;Diapositiva 3: Il paradosso del giocatore d&amp;#39;élite&quot;">​</a></h2><h3 id="hai-gia-le-competenze-allora-perche" tabindex="-1">Hai già le competenze... Allora perché? <a class="header-anchor" href="#hai-gia-le-competenze-allora-perche" aria-label="Permalink to &quot;Hai già le competenze... Allora perché?&quot;">​</a></h3><p><strong>✅ HAI:</strong></p><ul><li>Ottima tecnica (migliaia di ore)</li><li>Anni di esperienza</li><li>Capacità fisica</li></ul><p><strong>❌ Ma hai DIFFICOLTÀ con:</strong></p><ul><li>Accedere a quella tecnica sotto pressione</li><li>Mantenere la coerenza nella competizione</li><li>Riprendersi dopo gli errori</li></ul><h3 id="il-pezzo-mancante-🧩" tabindex="-1">Il pezzo mancante? 🧩 <a class="header-anchor" href="#il-pezzo-mancante-🧩" aria-label="Permalink to &quot;Il pezzo mancante? 🧩&quot;">​</a></h3><p><strong>Il tuo gioco mentale.</strong></p><p><em>&quot;La differenza tra il buono e l&#39;ottimo è ciò che accade tra le tue orecchie.&quot;</em></p><hr><h2 id="diapositiva-4-la-zona-conosci-questa-sensazione-⚡" tabindex="-1">Diapositiva 4: La Zona - Conosci questa sensazione! ⚡ <a class="header-anchor" href="#diapositiva-4-la-zona-conosci-questa-sensazione-⚡" aria-label="Permalink to &quot;Diapositiva 4: La Zona - Conosci questa sensazione! ⚡&quot;">​</a></h2><h3 id="ricordi-quella-partita-perfetta" tabindex="-1">Ricordi quella partita perfetta? <a class="header-anchor" href="#ricordi-quella-partita-perfetta" aria-label="Permalink to &quot;Ricordi quella partita perfetta?&quot;">​</a></h3><p><strong>Tutto sembrava:</strong></p><ul><li>⏱️ Il tempo rallenta</li><li>🎯 Senza sforzo e automatico</li><li>🧘 Completamente concentrato</li><li>🎪 Come se non potessi perderti</li></ul><h3 id="questa-e-quot-la-zona-quot-stato-di-flusso" tabindex="-1">Questa è &quot;La Zona&quot; (Stato di Flusso) <a class="header-anchor" href="#questa-e-quot-la-zona-quot-stato-di-flusso" aria-label="Permalink to &quot;Questa è &amp;quot;La Zona&amp;quot; (Stato di Flusso)&quot;">​</a></h3><p><strong>La domanda:</strong><em>Come possiamo accedervi in modo coerente, non solo per caso?</em></p><p><strong>La risposta:</strong><em>Capire i tuoi due modi di pensare...</em></p><hr><h2 id="diapositiva-5-il-tuo-cervello-ha-due-modalita-🧠" tabindex="-1">Diapositiva 5: Il tuo cervello ha due modalità 🧠 <a class="header-anchor" href="#diapositiva-5-il-tuo-cervello-ha-due-modalita-🧠" aria-label="Permalink to &quot;Diapositiva 5: Il tuo cervello ha due modalità 🧠&quot;">​</a></h2><h3 id="🤔-modalita-di-pianificazione-cervello-analitico" tabindex="-1">🤔 MODALITÀ DI PIANIFICAZIONE (Cervello Analitico) <a class="header-anchor" href="#🤔-modalita-di-pianificazione-cervello-analitico" aria-label="Permalink to &quot;🤔 MODALITÀ DI PIANIFICAZIONE (Cervello Analitico)&quot;">​</a></h3><p><strong>Quando usare:</strong> PRIMA dell&#39;iniezione</p><ul><li>📊 Analisi del terreno</li><li>🎯 Scegliere la tua strategia</li><li>⚖️ Valutare i rischi</li><li>🤝 Decidere lo scatto</li></ul><h3 id="🎯-modalita-di-esecuzione-flow-brain" tabindex="-1">🎯 MODALITÀ DI ESECUZIONE (Flow Brain) <a class="header-anchor" href="#🎯-modalita-di-esecuzione-flow-brain" aria-label="Permalink to &quot;🎯 MODALITÀ DI ESECUZIONE (Flow Brain)&quot;">​</a></h3><p><strong>Quando usare:</strong> DURANTE l&#39;iniezione</p><ul><li>💪 Fidarsi del proprio corpo</li><li>🚫 NON pensare alla tecnica</li><li>⏰ Solo momento presente</li><li>🤖 Prestazioni automatiche</li></ul><h3 id="⚠️-il-problema" tabindex="-1">⚠️ IL PROBLEMA: <a class="header-anchor" href="#⚠️-il-problema" aria-label="Permalink to &quot;⚠️ IL PROBLEMA:&quot;">​</a></h3><p><strong>La maggior parte dei giocatori rimane in modalità Pianificazione durante l&#39;esecuzione!</strong><em>Il tuo cervello analitico interferisce con le tue prestazioni automatiche.</em></p><hr><h2 id="diapositiva-6-the-switch-la-tua-arma-segreta-🔄" tabindex="-1">Diapositiva 6: The Switch - La tua arma segreta 🔄 <a class="header-anchor" href="#diapositiva-6-the-switch-la-tua-arma-segreta-🔄" aria-label="Permalink to &quot;Diapositiva 6: The Switch - La tua arma segreta 🔄&quot;">​</a></h2><h3 id="padroneggia-questa-abilita" tabindex="-1">Padroneggia questa abilità: <a class="header-anchor" href="#padroneggia-questa-abilita" aria-label="Permalink to &quot;Padroneggia questa abilità:&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BEFORE the shot:          DURING the shot:</span></span>\n<span class="line"><span>🤔 Planning Mode    →     🎯 Execution Mode</span></span></code></pre></div><h3 id="il-processo" tabindex="-1">Il processo: <a class="header-anchor" href="#il-processo" aria-label="Permalink to &quot;Il processo:&quot;">​</a></h3><p><strong>1️⃣ PRIMA (10-15 secondi):</strong></p><ul><li>🤔 Analizza tutto</li><li>📊 Pianifica la tua strategia</li><li>✅ Prendi la tua decisione</li></ul><p><strong>2️⃣ IL CAMBIO (3 respiri):</strong></p><ul><li>🌬️ Respira profondamente</li><li>🧘 Libera la mente</li><li>🔄 Lascia andare l&#39;analisi</li></ul><p><strong>3️⃣ DURANTE (2-3 secondi):</strong></p><ul><li>🎯 Fidati completamente</li><li>🤖 Lascia che accada</li><li>⚡ Esegui automaticamente</li></ul><p><strong>Metti in pratica questo passaggio = Accedi al flusso su richiesta!</strong></p><hr><h2 id="diapositiva-7-attivita-provala-subito-🎯" tabindex="-1">Diapositiva 7: ATTIVITÀ - Provala subito! 🎯 <a class="header-anchor" href="#diapositiva-7-attivita-provala-subito-🎯" aria-label="Permalink to &quot;Diapositiva 7: ATTIVITÀ - Provala subito! 🎯&quot;">​</a></h2><h3 id="mettiamo-in-pratica-lo-switch-2-minuti" tabindex="-1">Mettiamo in pratica lo Switch (2 minuti) <a class="header-anchor" href="#mettiamo-in-pratica-lo-switch-2-minuti" aria-label="Permalink to &quot;Mettiamo in pratica lo Switch (2 minuti)&quot;">​</a></h3><p><strong>Alzatevi tutti!</strong></p><ol><li><p><strong>Modalità di pianificazione (10 sec):</strong> Immagina di analizzare un tiro. Pensa al terreno, alla strategia, ai rischi.</p></li><li><p><strong>L&#39;interruttore (3 respiri):</strong> Fai 3 respiri profondi. Libera la mente a ogni espirazione.</p></li><li><p><strong>Modalità di esecuzione (3 sec):</strong> Immagina di lanciare. Senza pensarci. Solo fiducia e lasciati trasportare.</p></li></ol><p><strong>Come ti sei sentito? Diverso?</strong></p><p><em>Siediti e discutiamo...</em></p><hr><h2 id="diapositiva-8-incontra-il-tuo-critico-interiore-😈" tabindex="-1">Diapositiva 8: Incontra il tuo critico interiore 😈 <a class="header-anchor" href="#diapositiva-8-incontra-il-tuo-critico-interiore-😈" aria-label="Permalink to &quot;Diapositiva 8: Incontra il tuo critico interiore 😈&quot;">​</a></h2><h3 id="questa-voce-ti-suona-familiare" tabindex="-1">Questa voce ti suona familiare? <a class="header-anchor" href="#questa-voce-ti-suona-familiare" aria-label="Permalink to &quot;Questa voce ti suona familiare?&quot;">​</a></h3><p><strong>Dopo un brutto tiro:</strong></p><ul><li>💢 &quot;È stato TERRIBILE!&quot;</li><li>😤 &quot;Sotto pressione, sbagli SEMPRE!&quot;</li><li>😰 &quot;Tutti ti guardano fallire!&quot;</li><li>😞 &quot;Non sei abbastanza bravo!&quot;</li></ul><h3 id="sondaggio-rapido-🙋" tabindex="-1">Sondaggio rapido: 🙋 <a class="header-anchor" href="#sondaggio-rapido-🙋" aria-label="Permalink to &quot;Sondaggio rapido: 🙋&quot;">​</a></h3><p><strong>Chi sente regolarmente questa voce?</strong></p><h3 id="la-verita" tabindex="-1">La verità: <a class="header-anchor" href="#la-verita" aria-label="Permalink to &quot;La verità:&quot;">​</a></h3><p><strong>Il tuo critico interiore sta cercando di aiutarti...</strong><em>Ma in realtà sta distruggendo le tue prestazioni.</em></p><hr><h2 id="diapositiva-9-licenzia-il-tuo-critico-assumi-il-tuo-coach-🔄" tabindex="-1">Diapositiva 9: Licenzia il tuo critico, assumi il tuo coach! 🔄 <a class="header-anchor" href="#diapositiva-9-licenzia-il-tuo-critico-assumi-il-tuo-coach-🔄" aria-label="Permalink to &quot;Diapositiva 9: Licenzia il tuo critico, assumi il tuo coach! 🔄&quot;">​</a></h2><h3 id="la-trasformazione" tabindex="-1">La trasformazione: <a class="header-anchor" href="#la-trasformazione" aria-label="Permalink to &quot;La trasformazione:&quot;">​</a></h3><p>| 😈 Critico Interiore | ➡️ | 😊 Coach Interiore | |--------------------------------------|----------------| | &quot;Fai SEMPRE degli errori!&quot; | → | &quot;Ho già fatto questo scatto 1000 volte&quot; | | &quot;È stato TERRIBILE!&quot; | → | &quot;Cosa posso imparare da questo?&quot; | | &quot;Tutti ti giudicano!&quot; | → | &quot;Concentrati sul MIO gioco, non sulle loro opinioni&quot; | | &quot;Non sei abbastanza bravo!&quot; | → | &quot;Sto migliorando ogni giorno&quot; |</p><h3 id="l-39-impatto" tabindex="-1">L&#39;impatto: <a class="header-anchor" href="#l-39-impatto" aria-label="Permalink to &quot;L&amp;#39;impatto:&quot;">​</a></h3><p><strong>Critico = Ansia, tensione, scarse prestazioni</strong><strong>Coach = Fiducia, rilassamento, prestazioni al top</strong></p><hr><h2 id="diapositiva-10-attivita-riformula-il-tuo-critico-💬" tabindex="-1">Diapositiva 10: ATTIVITÀ - Riformula il tuo critico! 💬 <a class="header-anchor" href="#diapositiva-10-attivita-riformula-il-tuo-critico-💬" aria-label="Permalink to &quot;Diapositiva 10: ATTIVITÀ - Riformula il tuo critico! 💬&quot;">​</a></h2><h3 id="esercizio-in-coppia-3-minuti" tabindex="-1">Esercizio in coppia (3 minuti) <a class="header-anchor" href="#esercizio-in-coppia-3-minuti" aria-label="Permalink to &quot;Esercizio in coppia (3 minuti)&quot;">​</a></h3><p><strong>Rivolgiti alla persona accanto a te:</strong></p><p><strong>Persona A (1,5 min):</strong></p><ol><li>Condividi una cosa che dice il tuo critico interiore</li><li>Il partner ti aiuta a riformularlo come Coach Interiore</li><li>Scrivi la nuova frase</li></ol><p><strong>Persona B (1,5 min):</strong></p><ol><li>Stesso processo</li><li>Condividi il tuo pensiero di Critico Interiore</li><li>Ottieni aiuto per riformularlo</li></ol><p><strong>Pronti? Via!</strong></p><p><em>Condivideremo alcuni esempi con il gruppo dopo...</em></p><hr><h2 id="diapositiva-11-strumento-n-1-il-reset-dei-3-respiri-🌬️" tabindex="-1">Diapositiva 11: Strumento n. 1: Il reset dei 3 respiri 🌬️ <a class="header-anchor" href="#diapositiva-11-strumento-n-1-il-reset-dei-3-respiri-🌬️" aria-label="Permalink to &quot;Diapositiva 11: Strumento n. 1: Il reset dei 3 respiri 🌬️&quot;">​</a></h2><h3 id="la-tua-valvola-di-rilascio-della-pressione-di-emergenza" tabindex="-1">La tua valvola di rilascio della pressione di emergenza <a class="header-anchor" href="#la-tua-valvola-di-rilascio-della-pressione-di-emergenza" aria-label="Permalink to &quot;La tua valvola di rilascio della pressione di emergenza&quot;">​</a></h3><p><strong>Usa questo quando:</strong></p><ul><li>😤 Hai appena fatto un errore</li><li>😰 Senti che la pressione aumenta</li><li>🤯 La tua mente sta correndo</li></ul><h3 id="il-processo-1" tabindex="-1">Il processo: <a class="header-anchor" href="#il-processo-1" aria-label="Permalink to &quot;Il processo:&quot;">​</a></h3><p><strong>🌬️ RESPIRO 1 (Inspira per 4 sec):</strong> Nota dove senti tensione (spalle? mascella? stomaco?)</p><p><strong>🌬️ RESPIRO 2 (Espira 6 sec):</strong> Rilascia quella tensione. Lasciala fluire fuori con il respiro.</p><p><strong>🌬️ RESPIRO 3 (Inspirazione 4, Espirazione 6):</strong> Riconcentrati sul ORA. Su questo scatto. Su questo momento. Su nient&#39;altro.</p><p><strong>⏱️ Ci vogliono 20 secondi. Cambia tutto.</strong></p><hr><h2 id="diapositiva-12-demo-provatela-tutti-🌬️" tabindex="-1">Diapositiva 12: DEMO - Provatela tutti! 🌬️ <a class="header-anchor" href="#diapositiva-12-demo-provatela-tutti-🌬️" aria-label="Permalink to &quot;Diapositiva 12: DEMO - Provatela tutti! 🌬️&quot;">​</a></h2><h3 id="pratica-di-reset-dei-3-respiri-1-minuto" tabindex="-1">Pratica di reset dei 3 respiri (1 minuto) <a class="header-anchor" href="#pratica-di-reset-dei-3-respiri-1-minuto" aria-label="Permalink to &quot;Pratica di reset dei 3 respiri (1 minuto)&quot;">​</a></h3><p><strong>Chiudete tutti gli occhi...</strong></p><p><strong>Respiro 1:</strong><em>Inspira per 4... Dove senti la tensione?</em></p><p><strong>Respiro 2:</strong><em>Espira per 6... Lascia andare...</em></p><p><strong>Respiro 3:</strong><em>Dentro per 4, fuori per 6... Solo il momento presente...</em></p><p><strong>Apri gli occhi. Come ti senti?</strong></p><p><em>Questo è il tuo pulsante di reset. Usalo!</em></p><hr><h2 id="diapositiva-13-strumento-n-2-la-tua-routine-pre-tiro-🎯" tabindex="-1">Diapositiva 13: Strumento n. 2: la tua routine pre-tiro 🎯 <a class="header-anchor" href="#diapositiva-13-strumento-n-2-la-tua-routine-pre-tiro-🎯" aria-label="Permalink to &quot;Diapositiva 13: Strumento n. 2: la tua routine pre-tiro 🎯&quot;">​</a></h2><h3 id="costruisci-coerenza-automatica" tabindex="-1">Costruisci coerenza automatica <a class="header-anchor" href="#costruisci-coerenza-automatica" aria-label="Permalink to &quot;Costruisci coerenza automatica&quot;">​</a></h3><p><strong>La routine in 4 fasi:</strong></p><p><strong>1️⃣ VISUALIZZA (3 secondi)</strong> Immagina il tiro perfetto. Guardalo atterrare esattamente dove vuoi.</p><p><strong>2️⃣ RESPIRA (2 secondi)</strong> Un respiro profondo. Passa dalla modalità pianificazione a quella esecuzione.</p><p><strong>3️⃣ ANCORA (2 secondi)</strong> Tocca la tua boccia. Senti il peso. Connessione fisica.</p><p><strong>4️⃣ ESEGUI (2 secondi)</strong> Fidati completamente. Lascia che il tuo corpo faccia ciò che sa fare.</p><p><strong>⏱️ Totale: 9 secondi. Sempre lo stesso.</strong></p><h3 id="perche-funziona" tabindex="-1">Perché funziona: <a class="header-anchor" href="#perche-funziona" aria-label="Permalink to &quot;Perché funziona:&quot;">​</a></h3><p><strong>Coerenza = Fiducia = Performance</strong></p><hr><h2 id="diapositiva-14-strumento-n-3-protocollo-di-recupero-degli-errori-🔄" tabindex="-1">Diapositiva 14: Strumento n. 3 - Protocollo di recupero degli errori 🔄 <a class="header-anchor" href="#diapositiva-14-strumento-n-3-protocollo-di-recupero-degli-errori-🔄" aria-label="Permalink to &quot;Diapositiva 14: Strumento n. 3 - Protocollo di recupero degli errori 🔄&quot;">​</a></h2><h3 id="brutto-colpo-ecco-la-tua-strategia-di-recupero-in-4-fasi" tabindex="-1">Brutto colpo? Ecco la tua strategia di recupero in 4 fasi: <a class="header-anchor" href="#brutto-colpo-ecco-la-tua-strategia-di-recupero-in-4-fasi" aria-label="Permalink to &quot;Brutto colpo? Ecco la tua strategia di recupero in 4 fasi:&quot;">​</a></h3><p><strong>1️⃣ RICONOSCIMENTO (2 secondi)</strong> &quot;Non è andato come previsto.&quot; (Nessun giudizio, solo fatti)</p><p><strong>2️⃣ RILASCIO (3 secondi)</strong> Reset fisico: stringi le mani, ruota le spalle, fai 3 passi.</p><p><strong>3️⃣ RIFOCALIZZA (3 secondi)</strong> &quot;Il prossimo colpo è una NUOVA opportunità.&quot; (Non collegato all&#39;ultimo)</p><p><strong>4️⃣ ESEGUI (Usa la tua routine)</strong> Affidati alla tua routine pre-shot. Un nuovo inizio.</p><h3 id="l-39-intuizione-chiave" tabindex="-1">L&#39;intuizione chiave: <a class="header-anchor" href="#l-39-intuizione-chiave" aria-label="Permalink to &quot;L&amp;#39;intuizione chiave:&quot;">​</a></h3><p><strong>Ogni scatto è indipendente. Non riportare gli errori nel futuro.</strong></p><p><em>I giocatori migliori hanno la memoria più corta per i tiri sbagliati.</em></p><hr><h2 id="diapositiva-15-parliamo-sul-serio-cosa-ti-ferma-💬" tabindex="-1">Diapositiva 15: PARLIAMO SUL SERIO: Cosa ti ferma? 💬 <a class="header-anchor" href="#diapositiva-15-parliamo-sul-serio-cosa-ti-ferma-💬" aria-label="Permalink to &quot;Diapositiva 15: PARLIAMO SUL SERIO: Cosa ti ferma? 💬&quot;">​</a></h2><h3 id="discussione-di-gruppo-5-minuti" tabindex="-1">Discussione di gruppo (5 minuti) <a class="header-anchor" href="#discussione-di-gruppo-5-minuti" aria-label="Permalink to &quot;Discussione di gruppo (5 minuti)&quot;">​</a></h3><p><strong>Sentiamo cosa ne pensi:</strong></p><p><strong>Domanda 1:</strong><em>&quot;Quando ti senti PIÙ in flusso? Quali condizioni ti aiutano?&quot;</em></p><p><strong>Domanda 2:</strong><em>&quot;Qual è la tua più grande sfida mentale in gara?&quot;</em></p><p><strong>Domanda 3:</strong><em>&quot;Quale di questi strumenti ti sembra più vicino?&quot;</em></p><ul><li>3-Reset del respiro</li><li>Routine pre-tiro</li><li>Riformulazione del coach interiore</li><li>Recupero degli errori</li></ul><p><strong>Condividi apertamente: questo è uno spazio sicuro!</strong></p><hr><h2 id="diapositiva-16-il-tuo-piano-d-39-azione-scegline-uno-✅" tabindex="-1">Diapositiva 16: Il tuo piano d&#39;azione: scegline UNO! ✅ <a class="header-anchor" href="#diapositiva-16-il-tuo-piano-d-39-azione-scegline-uno-✅" aria-label="Permalink to &quot;Diapositiva 16: Il tuo piano d&amp;#39;azione: scegline UNO! ✅&quot;">​</a></h2><h3 id="la-sfida-di-questa-settimana" tabindex="-1">La sfida di questa settimana: <a class="header-anchor" href="#la-sfida-di-questa-settimana" aria-label="Permalink to &quot;La sfida di questa settimana:&quot;">​</a></h3><p><strong>Scegli SOLO UNA tecnica da praticare:</strong></p><p><strong>Opzione A: 🌬️ Reset con 3 respiri</strong> Da usare dopo OGNI errore nell&#39;allenamento</p><p><strong>Opzione B: 🎯 Routine pre-tiro</strong> Stessa routine in 4 fasi per OGNI lancio</p><p><strong>Opzione C: 💬 Coach Interiore</strong> Riformula UN pensiero critico per sessione</p><p><strong>Opzione D: 🔄 Cambio modalità</strong> Pianificazione della pratica → passaggio all&#39;esecuzione</p><h3 id="perche-solo-uno" tabindex="-1">Perché solo uno? <a class="header-anchor" href="#perche-solo-uno" aria-label="Permalink to &quot;Perché solo uno?&quot;">​</a></h3><p><strong>Impara a padroneggiare uno strumento prima di aggiungerne un altro.</strong><em>Nell&#39;allenamento mentale la profondità è più importante dell&#39;ampiezza.</em></p><hr><h2 id="diapositiva-17-tieni-traccia-dei-tuoi-progressi-📊" tabindex="-1">Diapositiva 17: Tieni traccia dei tuoi progressi 📊 <a class="header-anchor" href="#diapositiva-17-tieni-traccia-dei-tuoi-progressi-📊" aria-label="Permalink to &quot;Diapositiva 17: Tieni traccia dei tuoi progressi 📊&quot;">​</a></h2><h3 id="cosa-notare-questa-settimana" tabindex="-1">Cosa notare questa settimana: <a class="header-anchor" href="#cosa-notare-questa-settimana" aria-label="Permalink to &quot;Cosa notare questa settimana:&quot;">​</a></h3><p><strong>🎯 Momenti di Flow:</strong></p><ul><li>Quando ti sei sentito &quot;nella zona&quot;?</li><li>A che ora del giorno?</li><li>Che tipo di scatto?</li><li>Cosa ti ha aiutato ad arrivare fin qui?</li></ul><p><strong>💪 Tecnica di successo:</strong></p><ul><li>Quale strumento ha funzionato meglio?</li><li>Quando l&#39;hai usato?</li><li>Qual è stato il risultato?</li></ul><p><strong>📝 Tieni un registro semplice:</strong><em>&quot;Ho usato il reset a 3 respiri dopo un errore → mi sono sentito più calmo → ho fatto il tiro successivo&quot;</em></p><h3 id="l-39-obiettivo" tabindex="-1">L&#39;obiettivo: <a class="header-anchor" href="#l-39-obiettivo" aria-label="Permalink to &quot;L&amp;#39;obiettivo:&quot;">​</a></h3><p><strong>Trova i TUOI schemi. Costruisci il TUO sistema.</strong></p><hr><h2 id="diapositiva-18-continua-il-tuo-viaggio-🚀" tabindex="-1">Diapositiva 18: Continua il tuo viaggio 🚀 <a class="header-anchor" href="#diapositiva-18-continua-il-tuo-viaggio-🚀" aria-label="Permalink to &quot;Diapositiva 18: Continua il tuo viaggio 🚀&quot;">​</a></h2><h3 id="risorse-gratuite-su-carreau-app" tabindex="-1">Risorse gratuite su carreau.app: <a class="header-anchor" href="#risorse-gratuite-su-carreau-app" aria-label="Permalink to &quot;Risorse gratuite su carreau.app:&quot;">​</a></h3><p><strong>📚 Approfondimenti:</strong></p><ul><li><strong>La Zona</strong> - Stati di flusso master</li><li><strong>Forza mentale</strong> - Gestione avanzata della pressione</li><li><strong>Dinamiche di squadra</strong> - Comunicazione e fiducia</li><li><strong>Mindfulness</strong> - Concentrazione sul momento presente</li></ul><p><strong>🛠️ Strumenti pratici:</strong></p><ul><li><strong>Modello di obiettivo</strong> - Struttura il tuo sviluppo</li><li><strong>Modello di diario</strong> - Tieni traccia dei progressi giornalieri</li><li><strong>Guida al workshop</strong> - Gestisci le tue sessioni</li></ul><p><strong>Tutto gratuito. Tutto accessibile. Tutto progettato per giocatori d&#39;élite.</strong></p><hr><h2 id="diapositiva-19-le-4-grandi-idee-💡" tabindex="-1">Diapositiva 19: Le 4 grandi idee 💡 <a class="header-anchor" href="#diapositiva-19-le-4-grandi-idee-💡" aria-label="Permalink to &quot;Diapositiva 19: Le 4 grandi idee 💡&quot;">​</a></h2><h3 id="portateli-a-casa" tabindex="-1">Portateli a casa: <a class="header-anchor" href="#portateli-a-casa" aria-label="Permalink to &quot;Portateli a casa:&quot;">​</a></h3><p><strong>1️⃣ Il flusso è un&#39;ABILITÀ, non una questione di fortuna</strong> Puoi imparare ad accedervi su richiesta</p><p><strong>2️⃣ La tua voce interiore PLASMA le tue prestazioni</strong> Allenati, non criticarti</p><p><strong>3️⃣ Gli strumenti semplici FUNZIONANO sotto pressione</strong> 3 respiri. Una routine. Un reset. Tutto qui.</p><p><strong>4️⃣ La pratica rende PERMANENTI</strong> Le abilità mentali necessitano di allenamento come le abilità tecniche</p><h3 id="la-verita-1" tabindex="-1">La verità: <a class="header-anchor" href="#la-verita-1" aria-label="Permalink to &quot;La verità:&quot;">​</a></h3><p><strong>L&#39;allenamento mentale non è mistico. È pratico.</strong></p><hr><h2 id="diapositiva-20-domande-parliamone-💬" tabindex="-1">Diapositiva 20: Domande? Parliamone! 💬 <a class="header-anchor" href="#diapositiva-20-domande-parliamone-💬" aria-label="Permalink to &quot;Diapositiva 20: Domande? Parliamone! 💬&quot;">​</a></h2><h1 id="discussione-aperta" tabindex="-1">Discussione aperta <a class="header-anchor" href="#discussione-aperta" aria-label="Permalink to &quot;Discussione aperta&quot;">​</a></h1><p><strong>Quali domande hai?</strong></p><p><strong>Quali esperienze vuoi condividere?</strong></p><p><strong>Quali sfide stai affrontando?</strong></p><p><strong>Cosa proverai per primo?</strong></p><p><em>Questa è la TUA sessione. Rendiamola preziosa per TE.</em></p><hr><h2 id="diapositiva-21-la-tua-sfida-🎯" tabindex="-1">Diapositiva 21: La tua sfida 🎯 <a class="header-anchor" href="#diapositiva-21-la-tua-sfida-🎯" aria-label="Permalink to &quot;Diapositiva 21: La tua sfida 🎯&quot;">​</a></h2><h1 id="missione-di-questa-settimana" tabindex="-1">Missione di questa settimana: <a class="header-anchor" href="#missione-di-questa-settimana" aria-label="Permalink to &quot;Missione di questa settimana:&quot;">​</a></h1><p><strong>1️⃣ Scegli UNO strumento</strong> (Reset a 3 respiri, routine pre-tiro, coach interiore o cambio di modalità)</p><p><strong>2️⃣ Esercitati OGNI sessione</strong> (La coerenza supera l&#39;intensità)</p><p><strong>3️⃣ Nota cosa cambia</strong> (Tieni traccia dei tuoi progressi)</p><p><strong>4️⃣ Condividi i tuoi risultati</strong> (Con i tuoi compagni di allenamento o su carreau.app)</p><h3 id="ricordare" tabindex="-1">Ricordare: <a class="header-anchor" href="#ricordare" aria-label="Permalink to &quot;Ricordare:&quot;">​</a></h3><p><strong>Piccoli cambiamenti → Grandi risultati</strong></p><hr><h2 id="diapositiva-22-grazie-🙏" tabindex="-1">Diapositiva 22: Grazie! 🙏 <a class="header-anchor" href="#diapositiva-22-grazie-🙏" aria-label="Permalink to &quot;Diapositiva 22: Grazie! 🙏&quot;">​</a></h2><h1 id="ce-la-puoi-fare" tabindex="-1">Ce la puoi fare! <a class="header-anchor" href="#ce-la-puoi-fare" aria-label="Permalink to &quot;Ce la puoi fare!&quot;">​</a></h1><p><strong>Cosa hai imparato oggi:</strong></p><ul><li>✅ Come accedere agli stati di flusso</li><li>✅ Come gestire il tuo critico interiore</li><li>✅ Strumenti pratici che funzionano sotto pressione</li><li>✅ Un piano d&#39;azione chiaro per questa settimana</li></ul><p><strong>Passaggi successivi:</strong></p><ol><li>Scegli la tua tecnica UNICA</li><li>Praticalo costantemente</li><li>Visita carreau.app per ulteriori risorse</li><li>Condividi i tuoi progressi con il gruppo</li></ol><h3 id="il-viaggio-inizia-ora" tabindex="-1">Il viaggio inizia ora: <a class="header-anchor" href="#il-viaggio-inizia-ora" aria-label="Permalink to &quot;Il viaggio inizia ora:&quot;">​</a></h3><p><strong>L&#39;allenamento mentale è pratico, non mistico.</strong><strong>Inizia oggi. Scopri i risultati presto.</strong></p><hr><p><em>Accademia di bocce - Sviluppo dei giocatori d&#39;élite</em><em>carreau.app - Risorse gratuite per giocatori d&#39;élite</em></p>',201)])])}]]);export{t as __pageData,r as default};
